#include <sys/stat.h>
#include <sys/mount.h>
#include <sys/attr.h>
#include <fcntl.h>
#include <dirent.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void must(int bad,const char*s){if(bad){perror(s);exit(2);}}
static void unhex(const char *s,char *out){size_t n=strlen(s);must(n%2||n>2048,"hex length");for(size_t i=0;i<n;i+=2){unsigned x=0;must(sscanf(s+i,"%2x",&x)!=1||!x,"invalid hex");out[i/2]=(char)x;}out[n/2]=0;}
static void hex(const char*s){putchar('"');for(size_t i=0;i<strlen(s);i++)printf("%02x",(unsigned char)s[i]);putchar('"');}
int main(int argc,char **argv){if(argc!=3)return 2;int root=open(argv[1],O_RDONLY|O_DIRECTORY);must(root<0,"root");must(mkdirat(root,"collation",0700),"create owned corpus");int base=openat(root,"collation",O_RDONLY|O_DIRECTORY);must(base<0,"corpus");struct statfs fs;must(fstatfs(base,&fs),"filesystem");struct attrlist attrs={0};attrs.bitmapcount=ATTR_BIT_MAP_COUNT;attrs.volattr=ATTR_VOL_INFO|ATTR_VOL_CAPABILITIES;struct __attribute__((packed)){uint32_t length;vol_capabilities_attr_t value;} caps;must(fgetattrlist(base,&attrs,&caps,sizeof(caps),0),"capabilities");must(!(caps.value.valid[VOL_CAPABILITIES_FORMAT]&VOL_CAP_FMT_CASE_SENSITIVE),"unknown case sensitivity");printf("{\"filesystem\":\"%s\",\"mount_flags\":%u,\"capabilities\":[%u,%u,%u,%u],\"valid\":[%u,%u,%u,%u],\"case_sensitive\":%s,\"cases\":[",fs.f_fstypename,fs.f_flags,caps.value.capabilities[0],caps.value.capabilities[1],caps.value.capabilities[2],caps.value.capabilities[3],caps.value.valid[0],caps.value.valid[1],caps.value.valid[2],caps.value.valid[3],caps.value.capabilities[VOL_CAPABILITIES_FORMAT]&VOL_CAP_FMT_CASE_SENSITIVE?"true":"false");FILE*input=fopen(argv[2],"r");must(!input,"cases");char*line=NULL;size_t cap=0;int first=1,count=0;while(getline(&line,&cap,input)>=0){line[strcspn(line,"\n")]=0;char*id=strtok(line,"\t"),*created=strtok(NULL,"\t"),*queried=strtok(NULL,"\t");must(!id||!created||!queried||strtok(NULL,"\t"),"case fields");must(mkdirat(base,id,0700),"case directory");int dir=openat(base,id,O_RDONLY|O_DIRECTORY);must(dir<0,"case root");char a[1025],b[1025];unhex(created,a);unhex(queried,b);errno=0;int file=openat(dir,a,O_CREAT|O_EXCL|O_RDWR,0600);int ce=file<0?errno:0;struct stat before={0},after={0},parent={0};must(fstat(dir,&parent),"parent stat");if(file>=0)must(fstat(file,&before),"created stat");errno=0;int probe=openat(dir,b,O_RDONLY);int qe=probe<0?errno:0;if(probe>=0)must(fstat(probe,&after),"queried stat");char stored[4096]={0};uint64_t stored_inode=0;int duplicate=dup(dir);must(duplicate<0,"duplicate directory");DIR*stream=fdopendir(duplicate);must(!stream,"directory stream");struct dirent*de;for(;;){errno=0;de=readdir(stream);if(!de){must(errno,"read directory");break;}if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;must(stored_inode!=0||strlen(de->d_name)>=sizeof(stored),"unexpected directory inventory");strcpy(stored,de->d_name);stored_inode=de->d_ino;}must(closedir(stream),"close directory stream");
printf("%s{\"id\":\"%s\",\"created\":\"%s\",\"queried\":\"%s\",\"create_errno\":%d,\"lookup_errno\":%d,\"same_inode\":%s,\"parent_inode\":%llu,\"created_inode\":%llu,\"queried_inode\":%llu,\"stored_inode\":%llu,\"stored\":",first?"":",",id,created,queried,ce,qe,file>=0&&probe>=0&&before.st_dev==after.st_dev&&before.st_ino==after.st_ino?"true":"false",(unsigned long long)parent.st_ino,(unsigned long long)before.st_ino,(unsigned long long)after.st_ino,(unsigned long long)stored_inode);hex(stored);printf("}");first=0;count++;if(probe>=0)must(close(probe),"close probe");if(file>=0)must(close(file),"close created");must(close(dir),"close case");}must(ferror(input),"read cases");free(line);must(fclose(input),"close cases");must(close(base),"close base");must(close(root),"close root");printf("],\"count\":%d,\"owned_files_retained\":true}\n",count);return 0;}
